describe('handle', () => {
  let baseConfig: ConnectorConfig
  let fetchMock: typeof fetch
  let calls: Array<{ method: string; url: string; body: string | undefined; json: unknown; headers: Headers }>

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({ ok: true, channel: 'C123ABC456', ts: '1745594400.000200' })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetchMock = fetch
    calls = recordedCalls
    baseConfig = {
      shopifySharedSecret: 'test-shared-secret',
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C123ABC456',
      fetch: fetchMock,
    }
  })

  it('posts formatted message to Slack on happy path', async () => {
    const payload: ShopifyWebhookPayload = {
      id: 'gid://shopify/Order/123',
      name: '#1001',
      email: 'customer@example.com',
      total_price: '150.00',
      currency: 'USD',
      line_items: [
        {
          id: 'gid://shopify/LineItem/1',
          item: { title: 'Widget A', price: '100.00' },
          quantity: { original: 1, total: 1, fulfilled: 1 },
        },
        {
          id: 'gid://shopify/LineItem/2',
          item: { title: 'Widget B', price: '50.00' },
          quantity: { original: 1, total: 1, fulfilled: 0 },
        },
      ],
    }

    const result = await handle(payload, baseConfig)

    expect(calls.length).toBe(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://slack.com/api/chat.postMessage')
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
    expect(calls[0].headers.get('content-type')).toBe('application/json')

    const sentBody = calls[0].json as { channel: string; text: string }
    expect(sentBody.channel).toBe('C123ABC456')
    expect(sentBody.text).toBe('Order #1001 from customer@example.com for $150.00 USD\nItems: Widget A (1), Widget B (1)')

    expect(result.slackChannel).toBe('C123ABC456')
    expect(result.slackMessageTs).toBe('1745594400.000200')
  })

  it('throws on missing required field', async () => {
    const payload = { ...SOURCE_EXAMPLE, email: '' } as unknown as ShopifyWebhookPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: email')
    expect(calls.length).toBe(0)
  })

  it('throws on empty line_items array', async () => {
    const payload = { ...SOURCE_EXAMPLE, line_items: [] } as unknown as ShopifyWebhookPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('line_items must be a non-empty array')
    expect(calls.length).toBe(0)
  })

  it('throws on non-2xx response from Slack', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'channel_not_found' }, 404))
    const config = { ...baseConfig, fetch }

    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyWebhookPayload, config)).rejects.toThrow(
      'Slack API error: 404 Not Found at POST https://slack.com/api/chat.postMessage'
    )
    expect(errorCalls.length).toBe(1)
  })

  it('throws when Slack returns ok=false', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ ok: false, error: 'invalid_auth' }, 200))
    const config = { ...baseConfig, fetch }

    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyWebhookPayload, config)).rejects.toThrow(
      'Slack API returned ok=false: {"ok":false,"error":"invalid_auth"}'
    )
    expect(errorCalls.length).toBe(1)
  })

  it('uses custom fetch when provided in config', async () => {
    const customFetch = vi.fn(async () => jsonResponse({ ok: true, channel: 'C999', ts: '123.456' }))
    const config = { ...baseConfig, fetch: customFetch }

    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyWebhookPayload, config)

    expect(customFetch).toHaveBeenCalledTimes(1)
    expect(result.slackChannel).toBe('C999')
    expect(result.slackMessageTs).toBe('123.456')
  })
})

